@startuml

class HospitalHouseMD {}

class Patient {
  + Name : string
  + ID : int
}

class Doctor {
  + Name : string
  + PractitionerNumber : int
}

class HeadDoctor {
  + Name : string
}

class Diagnosis {
  + Description : string
  + Date : date
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class Treatment {
  + Name : string
  + Description : string
  + CurrentStage : int
}

class ConsentForm {
  + Signature : string
  + DateSigned : datetime
}

class Nurse {
  + Name : string
}

class TreatmentDatabase {}

HospitalHouseMD "1" *-- "1..*" Patient
HospitalHouseMD "1" *-- "1..*" Doctor
Doctor "1" -- "1..*" Patient
Doctor "1" -- "1..*" Diagnosis
HeadDoctor --|> Doctor
HeadDoctor "1" -- "1..*" Diagnosis : approves
Patient "1" -- "1..*" Diagnosis
Diagnosis "1" -- "1" Illness
HospitalHouseMD "1" *-- "1" TreatmentDatabase
TreatmentDatabase "1" -- "*" Treatment
Treatment "1" -- "1" Diagnosis
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "1..*" Treatment
Nurse "1" -- "*" Treatment
Doctor "1" -- "*" Treatment

@enduml

